/**
 * Sistema de Automa├º├úo do LEO
 * 
 * Leo executa rotinas autom├íticas:
 * - backup autom├ítico
 * - checagem estoque
 * - an├ílise vendas
 */

import { nanoid } from 'nanoid';
import { leoComputerControl } from './leo-computer-control.js';
import { leoErpService } from '../../services/leo-service.js';
import { ADMIN_ACTOR } from '../../_core/service-actor.js';
import { leoEvents } from '../memory/leo-events.js';
import { insertLeoActionLog } from '../../services/ai/leo-action-logger.js';

export type TaskStatus = 'pendente' | 'executando' | 'concluida' | 'falha' | 'cancelada';
export type TaskRecurrence = 'daily' | 'weekly' | 'monthly' | 'hourly' | 'none';

/** Tarefa agendada no sistema de automa├º├úo (diferente de LeoTask da fila shared) */
export interface LeoScheduledTask {
  id?: number;
  descricao: string;
  acao: string;
  agendamento?: Date;
  status: TaskStatus;
  dados?: unknown;
  resultado?: unknown;
  usuarioCriador?: string;
  dataCriacao?: Date;
  dataExecucao?: Date;
  proximaExecucao?: Date;
  recorrencia?: TaskRecurrence;
}

export interface CreateScheduledTaskInput {
  descricao: string;
  acao: string;
  agendamento?: Date;
  dados?: unknown;
  usuarioCriador?: string;
  recorrencia?: TaskRecurrence;
}

/**
 * Classe para automa├º├úo de tarefas pelo Leo
 */
export class LeoAutomation {
  private static instance: LeoAutomation;
  private isRunning: boolean = false;
  private taskQueue: Map<number, NodeJS.Timeout> = new Map();

  private constructor() {}

  public static getInstance(): LeoAutomation {
    if (!LeoAutomation.instance) {
      LeoAutomation.instance = new LeoAutomation();
    }
    return LeoAutomation.instance;
  }

  /**
   * Inicia o sistema de automa├º├úo
   */
  async iniciarAutomacao(): Promise<{ success: boolean; message: string }> {
    if (this.isRunning) {
      return {
        success: false,
        message: 'Sistema de automa├º├úo j├í est├í ativo',
      };
    }

    try {
      console.log('[LeoAutomation] Iniciando sistema de automa├º├úo');
      
      this.isRunning = true;
      
      // Carregar tarefas pendentes
      await this.carregarTarefasPendentes();
      
      // Iniciar verifica├º├úo peri├│dica
      this.iniciarVerificacaoPeriodica();
      
      console.log('[LeoAutomation] Sistema de automa├º├úo iniciado com sucesso');
      
      return {
        success: true,
        message: 'Sistema de automa├º├úo iniciado',
      };
    } catch (error) {
      console.error('[LeoAutomation] Erro ao iniciar automa├º├úo:', error);
      
      // Garantir que o sistema continue operando mesmo em caso de erro
      this.isRunning = false;
      
      // Registrar erro mas n├úo derrubar sistema
      try {
        await insertLeoActionLog({
          usuario: 'leo-automation',
          acao: 'erro_inicializacao',
          entidade: 'leo_automation',
          dados: JSON.stringify({
            error: error instanceof Error ? error.message : error,
            timestamp: new Date(),
          }),
          resultado: 'ERRO',
        });
      } catch (logError) {
        console.error('[LeoAutomation] Erro ao registrar log:', logError);
      }
      
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao iniciar automa├º├úo',
      };
    }
  }

  /**
   * Para o sistema de automa├º├úo
   */
  pararAutomacao(): { success: boolean; message: string } {
    if (!this.isRunning) {
      return {
        success: false,
        message: 'Sistema de automa├º├úo n├úo est├í ativo',
      };
    }

    try {
      // Cancelar todas as tarefas agendadas
      for (const [, timeout] of Array.from(this.taskQueue.entries())) {
        clearTimeout(timeout);
      }
      this.taskQueue.clear();
      
      this.isRunning = false;
      
      console.log('[LeoAutomation] Sistema de automa├º├úo parado');
      
      return {
        success: true,
        message: 'Sistema de automa├º├úo parado',
      };
    } catch (error) {
      console.error('[LeoAutomation] Erro ao parar automa├º├úo:', error);
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao parar automa├º├úo',
      };
    }
  }

  /**
   * Cria uma nova tarefa
   * TODO: Implementar quando tabela leoTasks for criada
   */
  async criarTarefa(input: CreateScheduledTaskInput): Promise<{ success: boolean; taskId?: number; message: string }> {
    console.warn('[LeoAutomation] criarTarefa n├úo implementado - tabela leoTasks n├úo existe');
    return {
      success: false,
      message: 'Tabela leoTasks n├úo implementada',
    };
  }

  /**
   * Executa uma tarefa espec├¡fica.
   * Stub: leoTasks removido ÔÇö usar leoMemory quando implementado.
   */
  async executarTarefa(_taskId: number): Promise<{ success: boolean; message: string }> {
    return {
      success: false,
      message: 'Tarefa n├úo encontrada (leoTasks substitu├¡do por leoMemory ÔÇö em implementa├º├úo)',
    };
  }

  /**
   * Lista tarefas com filtros.
   * Stub: leoTasks removido ÔÇö usar leoMemory quando implementado.
   */
  async listarTarefas(_filtros?: {
    status?: TaskStatus;
    acao?: string;
    usuarioCriador?: string;
    dataInicio?: Date;
    dataFim?: Date;
    limite?: number;
  }): Promise<{ success: boolean; tarefas?: LeoScheduledTask[]; message: string }> {
    return {
      success: true,
      tarefas: [],
      message: '0 tarefa(s) encontrada(s) (leoTasks substitu├¡do por leoMemory ÔÇö em implementa├º├úo)',
    };
  }

  /**
   * Cancela uma tarefa.
   * Stub: leoTasks removido ÔÇö usar leoMemory quando implementado.
   */
  async cancelarTarefa(taskId: number): Promise<{ success: boolean; message: string }> {
    if (this.taskQueue.has(taskId)) {
      clearTimeout(this.taskQueue.get(taskId)!);
      this.taskQueue.delete(taskId);
    }
    return {
      success: true,
      message: `Tarefa ${taskId} cancelada (stub: leoTasks em migra├º├úo para leoMemory)`,
    };
  }

  /**
   * Executa uma a├º├úo espec├¡fica
   */
  private async executarAcao(acao: string, dados: any): Promise<{ success: boolean; message: string; data?: any }> {
    try {
      console.log(`[LeoAutomation] Executando a├º├úo: ${acao}`);

      switch (acao) {
        case 'backup_automatico':
          return await this.executarBackupAutomatico(dados);
        
        case 'checar_estoque':
          return await this.checarEstoque(dados && typeof dados === "object" ? (dados as Record<string, unknown>) : {});
        
        case 'analisar_vendas':
          return await this.analisarVendas(dados && typeof dados === "object" ? (dados as Record<string, unknown>) : {});
        
        case 'limpar_logs_antigos':
          return await this.limparLogsAntigos(dados);
        
        case 'verificar_eventos_automaticos':
          return await this.verificarEventosAutomaticos(dados);
        
        case 'executar_script':
          return await this.executarScriptPersonalizado(dados);
        
        default:
          return {
            success: false,
            message: `A├º├úo desconhecida: ${acao}`,
          };
      }
    } catch (error) {
      console.error('[LeoAutomation] Erro ao executar a├º├úo:', error);
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao executar a├º├úo',
      };
    }
  }

  /**
   * Executa backup autom├ítico
   */
  private async executarBackupAutomatico(dados: any): Promise<{ success: boolean; message: string; data?: any }> {
    try {
      console.log('[LeoAutomation] Executando backup autom├ítico');
      
      const resultado = await leoComputerControl.executarScriptSistema('backup_db');
      
      if (resultado.success) {
        await leoEvents.registerEvent({
          tipo: 'custom',
          descricao: 'Backup autom├ítico executado com sucesso',
          prioridade: 'baixa',
          dados: { stdout: resultado.stdout },
          usuarioCriador: 'leo',
        });
      }

      return {
        success: resultado.success,
        message: resultado.success ? 'Backup autom├ítico executado' : 'Falha no backup autom├ítico',
        data: resultado,
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro no backup autom├ítico',
      };
    }
  }

  /**
   * Checa estoque e gera alertas
   */
  private async checarEstoque(dados: Record<string, unknown>): Promise<{ success: boolean; message: string; data?: unknown }> {
    try {
      console.log('[LeoAutomation] Checando estoque');
      const fromPayload = Number(dados.tenantId);
      const fromEnv = Number(process.env.TENANT_ID);
      const tenantId = Number.isFinite(fromPayload) && fromPayload > 0 ? fromPayload : fromEnv;
      if (!tenantId) {
        return { success: false, message: 'tenantId n├úo configurado (contexto ou TENANT_ID)' };
      }
      const resultado = await leoErpService.getEstoque(tenantId, { alertaBaixo: true });
      
      if (resultado.success && resultado.alertas) {
        const { estoqueBaixo, estoqueCritico } = resultado.alertas;
        
        if (estoqueCritico > 0) {
          await leoEvents.registerEvent({
            tipo: 'estoque_baixo',
            descricao: `${estoqueCritico} produtos com estoque cr├¡tico`,
            prioridade: 'critica',
            dados: { estoqueCritico, estoqueBaixo },
            usuarioCriador: 'leo',
          });
        }
      }

      return {
        success: true,
        message: 'Estoque checado',
        data: resultado,
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao checar estoque',
      };
    }
  }

  /**
   * Analisa vendas
   */
  private async analisarVendas(dados: Record<string, unknown>): Promise<{ success: boolean; message: string; data?: unknown }> {
    try {
      console.log('[LeoAutomation] Analisando vendas');
      const fromPayload = Number(dados.tenantId);
      const fromEnv = Number(process.env.TENANT_ID);
      const tenantId = Number.isFinite(fromPayload) && fromPayload > 0 ? fromPayload : fromEnv;
      if (!tenantId) {
        return { success: false, message: 'tenantId n├úo configurado (contexto ou TENANT_ID)' };
      }
      // Obter pedidos dos ├║ltimos 7 dias
      const seteDiasAtras = new Date();
      seteDiasAtras.setDate(seteDiasAtras.getDate() - 7);
      
      const resultado = await leoErpService.getPedidos(tenantId, ADMIN_ACTOR, {
        dataInicio: seteDiasAtras,
        limite: 1000,
      });
      
      if (resultado.success) {
        const totalPedidos = resultado.total || 0;
        const rows = Array.isArray(resultado.data) ? resultado.data : [];
        const valorTotal = rows.reduce((sum: number, p: unknown) => {
          const row = p as { pedido?: { valorTotal?: unknown } };
          return sum + Number(row.pedido?.valorTotal ?? 0);
        }, 0);
        
        // Gerar evento se vendas estiverem baixas
        if (totalPedidos < 5) {
          await leoEvents.registerEvent({
            tipo: 'custom',
            descricao: `Vendas baixas na semana: ${totalPedidos} pedidos`,
            prioridade: 'media',
            dados: { totalPedidos, valorTotal, periodo: '7 dias' },
            usuarioCriador: 'leo',
          });
        }
      }

      return {
        success: true,
        message: 'An├ílise de vendas conclu├¡da',
        data: resultado,
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro na an├ílise de vendas',
      };
    }
  }

  /**
   * Limpa logs antigos
   */
  private async limparLogsAntigos(dados: any): Promise<{ success: boolean; message: string; data?: any }> {
    try {
      console.log('[LeoAutomation] Limpando logs antigos');
      
      // Simula├º├úo - em produ├º├úo implementar limpeza real
      const diasReter = dados?.dias || 30;
      
      return {
        success: true,
        message: `Logs antigos removidos (per├¡odo: ${diasReter} dias)`,
        data: { diasReter, logsRemovidos: 0 },
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao limpar logs',
      };
    }
  }

  /**
   * Verifica eventos autom├íticos
   */
  private async verificarEventosAutomaticos(dados: any): Promise<{ success: boolean; message: string; data?: any }> {
    try {
      console.log('[LeoAutomation] Verificando eventos autom├íticos');
      
      const resultado = await leoEvents.gerarEventosAutomaticos();
      
      return {
        success: true,
        message: `${resultado.events.length} eventos gerados automaticamente`,
        data: resultado,
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao verificar eventos',
      };
    }
  }

  /**
   * Executa script personalizado
   */
  private async executarScriptPersonalizado(dados: any): Promise<{ success: boolean; message: string; data?: any }> {
    try {
      const scriptPath = dados?.scriptPath;
      if (!scriptPath) {
        return {
          success: false,
          message: 'Caminho do script n├úo fornecido',
        };
      }

      console.log(`[LeoAutomation] Executando script personalizado: ${scriptPath}`);
      
      const resultado = await leoComputerControl.executarScript(scriptPath, dados?.args);
      
      return {
        success: resultado.success,
        message: resultado.success ? 'Script executado' : 'Falha no script',
        data: resultado,
      };
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'Erro ao executar script',
      };
    }
  }

  /**
   * Carrega tarefas pendentes do banco.
   * Stub: leoTasks removido ÔÇö usar leoMemory quando implementado.
   */
  private async carregarTarefasPendentes(): Promise<void> {
    // Nenhuma tarefa enquanto leoTasks n├úo for migrado para leoMemory
  }

  /**
   * Agenda uma tarefa para execu├º├úo.
   * Stub: leoTasks removido ÔÇö usar leoMemory quando implementado.
   */
  private async agendarTarefa(_taskId: number): Promise<void> {
    // Nenhum agendamento enquanto leoTasks n├úo for migrado para leoMemory
  }

  /**
   * Inicia verifica├º├úo peri├│dica de tarefas
   */
  private iniciarVerificacaoPeriodica(): void {
    setInterval(async () => {
      if (!this.isRunning) return;
      
      try {
        await this.carregarTarefasPendentes();
      } catch (error) {
        console.error('[LeoAutomation] Erro na verifica├º├úo peri├│dica:', error);
      }
    }, 60000); // Verificar a cada minuto
  }

  /**
   * Calcula pr├│xima execu├º├úo baseada na recorr├¬ncia
   */
  private calcularProximaExecucao(recorrencia: TaskRecurrence, dataBase?: Date): Date {
    const base = dataBase || new Date();
    const proxima = new Date(base);

    switch (recorrencia) {
      case 'hourly':
        proxima.setHours(proxima.getHours() + 1);
        break;
      case 'daily':
        proxima.setDate(proxima.getDate() + 1);
        break;
      case 'weekly':
        proxima.setDate(proxima.getDate() + 7);
        break;
      case 'monthly':
        proxima.setMonth(proxima.getMonth() + 1);
        break;
      case 'none':
      default:
        // Sem recorr├¬ncia
        break;
    }

    return proxima;
  }

  /**
   * Verifica se a automa├º├úo est├í ativa
   */
  isAutomacaoAtiva(): boolean {
    return this.isRunning;
  }

  /**
   * Obt├®m estat├¡sticas das tarefas
   */
  async getEstatisticas(): Promise<{
    total: number;
    porStatus: Record<TaskStatus, number>;
    porAcao: Record<string, number>;
    proximasExecucoes: Array<{ id: number; descricao: string; data: Date }>;
  }> {
    return {
      total: 0,
      porStatus: {} as Record<TaskStatus, number>,
      porAcao: {} as Record<string, number>,
      proximasExecucoes: [],
    };
  }
}

// Exportar inst├óncia singleton
export const leoAutomation = LeoAutomation.getInstance();

import * as configuracoesService from "../../services/configuracoes.service.js";

const PREFIX = "leo_memory_";
function getDefaultTenantId(): number {
  const tenantId = Number(process.env.TENANT_ID);
  if (!tenantId || tenantId <= 0) {
    throw new Error("Tenant ID obrigat├│rio para mem├│ria do LEO");
  }
  return tenantId;
}

function key(tenantId: number, usuario: string, chave: string): string {
  return `${PREFIX}${tenantId}_${usuario}_${chave}`;
}

export async function getMemoria(usuario: string, chave: string, tenantId: number = getDefaultTenantId()): Promise<string | null> {
  try {
    const valor = await configuracoesService.getConfig(key(tenantId, usuario, chave));
    return valor ?? null;
  } catch {
    return null;
  }
}

export async function setMemoria(usuario: string, chave: string, valor: string, tenantId: number = getDefaultTenantId()): Promise<void> {
  try {
    await configuracoesService.setConfig(key(tenantId, usuario, chave), valor);
  } catch (e) {
    console.error("[LEO memory] Erro ao setMemoria:", (e as Error)?.message ?? e);
    throw e;
  }
}

export async function listarChavesMemoria(usuario: string, tenantId: number = getDefaultTenantId()): Promise<string[]> {
  try {
    const pattern = `${PREFIX}${tenantId}_${usuario}_%`;
    const chaves = await configuracoesService.listConfigKeysLike(pattern);
    const prefix = `${PREFIX}${tenantId}_${usuario}_`;
    return chaves.map((c) => c.replace(prefix, ""));
  } catch (e) {
    console.error("[LEO memory] Erro ao listarChavesMemoria:", (e as Error)?.message ?? e);
    return [];
  }
}

export async function removerMemoria(usuario: string, chaveMemoria: string, tenantId: number = getDefaultTenantId()): Promise<void> {
  try {
    await configuracoesService.deleteConfigByChave(key(tenantId, usuario, chaveMemoria));
  } catch (e) {
    console.error("[LEO memory] Erro ao removerMemoria:", (e as Error)?.message ?? e);
    throw e;
  }
}

/**
 * Log de a├º├Áes do LEO ÔÇö auditoria de execu├º├úo de tools.
 * N├úo bloqueia execu├º├úo; se falhar, ignora silenciosamente.
 * Usa insertLeoActionLog (db/index) ÔÇö tabela leo_action_logs compat├¡vel.
 */

import { insertLeoActionLog } from "../leo-action-log.service.js";

export type LeoActionLogContext = {
  tenantId: number;
  userId?: number;
};

export type LeoActionLogInput = {
  tool: string;
  input: unknown;
  result: unknown;
  success: boolean;
  executionTime: number;
  ctx: LeoActionLogContext;
};

/**
 * Registra uma execu├º├úo de tool. Ass├¡ncrono e fire-and-forget.
 * Falhas s├úo ignoradas para n├úo bloquear o fluxo.
 */
export async function logAction(params: LeoActionLogInput): Promise<void> {
  const { tool, input, result, success, ctx } = params;
  try {
    const inputStr = typeof input === "object" && input !== null ? JSON.stringify(input) : String(input);
    const resultStr =
      typeof result === "object" && result !== null ? JSON.stringify(result) : String(result ?? "");
    await insertLeoActionLog({
      usuario: `tenant:${ctx.tenantId}`,
      acao: tool,
      entidade: "leo_action",
      dados: inputStr.length > 65535 ? inputStr.slice(0, 65535) : inputStr,
      resultado: success ? "SUCESSO" : resultStr.slice(0, 500),
    });
  } catch {
    // Ignorar silenciosamente ÔÇö log n├úo pode bloquear execu├º├úo
  }
}

type LegacyLeoActionLogInput = {
  usuario: string;
  acao: string;
  entidade: string;
  dados?: string | null;
  resultado: string;
};

/**
 * Compatibilidade com chamadas legadas do LEO.
 * Mant├®m o mesmo nome de fun├º├úo esperada nos m├│dulos antigos.
 */
export async function insertLeoActionLogCompat(params: LegacyLeoActionLogInput): Promise<void> {
  try {
    const tenantMatch = params.usuario.match(/tenant:(\d+)/i);
    const tenantId = tenantMatch ? Number(tenantMatch[1]) : Number(process.env.TENANT_ID);
    if (!tenantId || tenantId <= 0) return;
    await logAction({
      tool: params.acao || "unknown",
      input: params.dados ?? "",
      result: params.resultado,
      success: String(params.resultado || "").toUpperCase() === "SUCESSO",
      executionTime: 0,
      ctx: { tenantId },
    });
  } catch {
    // Compat logger n├úo deve interromper fluxo
  }
}

export { insertLeoActionLogCompat as insertLeoActionLog };

import { insertLeoActionLog as insertLeoActionLogCore } from "../db/core.js";

export { insertLeoActionLogCore as insertLeoActionLog };

export async function insertLeoLegacyActionLog(params: {
  usuario: string;
  acao: string;
  entidade: string;
  dados?: string | null;
  resultado: string;
}): Promise<void> {
  const tenantMatch = params.usuario.match(/tenant:(\d+)/i);
  const tenantId = tenantMatch
    ? Number(tenantMatch[1])
    : Number(process.env.TENANT_ID);
  if (!Number.isFinite(tenantId) || tenantId <= 0) return;
  try {
    await insertLeoActionLogCore({
      tenantId,
      usuario: params.usuario,
      acao: params.acao,
      entidade: params.entidade,
      dados: params.dados ?? null,
      resultado: params.resultado,
    });
  } catch {
    void 0;
  }
}

/**
 * Ferramenta de Diagn├│stico Autom├ítico do Sistema ERP
 * 
 * Arquitetura: LEO ÔåÆ TOOLS ÔåÆ SERVICES ÔåÆ DATABASE
 * LEO nunca acessa DB direto.
 */

import { logger, systemLogger } from '../_core/logger.js';
import {
  checkDiagnosticDatabaseHealth,
  registerDiagnosticAudit,
} from '../services/system-diagnostic.service.js';

function getDiagnosticTenantId(): number | null {
  const raw = process.env.TENANT_ID;
  const value = Number(raw);
  return Number.isFinite(value) && value > 0 ? value : null;
}

export interface DiagnosticResult {
  timestamp: Date;
  systemHealth: {
    status: 'healthy' | 'warning' | 'critical';
    uptime: number;
    memoryUsage: NodeJS.MemoryUsage;
    cpuUsage: NodeJS.CpuUsage;
  };
  databaseHealth: {
    status: 'connected' | 'disconnected' | 'slow';
    connectionTime?: number;
    avgQueryTime?: number;
    slowQueries: Array<{
      query: string;
      duration: number;
      timestamp: Date;
    }>;
  };
  routeHealth: {
    totalRoutes: number;
    errorRate: number;
    avgResponseTime: number;
    errors: Array<{
      route: string;
      error: string;
      timestamp: Date;
    }>;
  };
  queueHealth: {
    status: 'active' | 'stalled' | 'empty';
    pendingJobs: number;
    processingJobs: number;
    failedJobs: number;
  };
  serviceHealth: {
    [serviceName: string]: {
      status: 'healthy' | 'error';
      lastError?: string;
      errorCount: number;
    };
  };
}

class SystemDiagnostic {
  private static instance: SystemDiagnostic;
  private slowQueries: Array<{ query: string; duration: number; timestamp: Date }> = [];
  private routeErrors: Array<{ route: string; error: string; timestamp: Date }> = [];
  private serviceErrors: Map<string, number> = new Map();
  private diagnosticHistory: DiagnosticResult[] = [];

  private constructor() {}

  public static getInstance(): SystemDiagnostic {
    if (!SystemDiagnostic.instance) {
      SystemDiagnostic.instance = new SystemDiagnostic();
    }
    return SystemDiagnostic.instance;
  }

  /**
   * Executa diagn├│stico completo do sistema
   */
  public async runFullDiagnostic(): Promise<DiagnosticResult> {
    console.log('Iniciando diagn├│stico completo do sistema ERP');

    const result: DiagnosticResult = {
      timestamp: new Date(),
      systemHealth: await this.checkSystemHealth(),
      databaseHealth: await this.checkDatabaseHealth(),
      routeHealth: await this.checkRouteHealth(),
      queueHealth: await this.checkQueueHealth(),
      serviceHealth: await this.checkServiceHealth()
    };

    // Avaliar sa├║de geral
    this.evaluateOverallHealth(result);

    // Registrar no audit_log
    await this.registerDiagnosticResult(result);

    // Armazenar hist├│rico
    this.diagnosticHistory.push(result);
    if (this.diagnosticHistory.length > 100) {
      this.diagnosticHistory = this.diagnosticHistory.slice(-50);
    }

    return result;
  }

  /**
   * Verifica sa├║de do sistema (mem├│ria, CPU, uptime)
   */
  private async checkSystemHealth(): Promise<DiagnosticResult['systemHealth']> {
    const memUsage = process.memoryUsage();
    const cpuUsage = process.cpuUsage();
    const uptime = process.uptime();

    let status: 'healthy' | 'warning' | 'critical' = 'healthy';

    // Verificar uso de mem├│ria
    const memoryUsagePercent = (memUsage.heapUsed / memUsage.heapTotal) * 100;
    if (memoryUsagePercent > 90) {
      status = 'critical';
    } else if (memoryUsagePercent > 75) {
      status = 'warning';
    }

    // Verificar uptime
    if (uptime < 60) { // menos de 1 minuto
      status = status === 'critical' ? 'critical' : 'warning';
    }

    return {
      status,
      uptime,
      memoryUsage: memUsage,
      cpuUsage
    };
  }

  /**
   * Verifica sa├║de do banco de dados
   */
  private async checkDatabaseHealth(): Promise<DiagnosticResult['databaseHealth']> {
    try {
      const result = await checkDiagnosticDatabaseHealth(this.slowQueries);
      
      if (!result.success) {
        console.error('Erro no diagn├│stico do banco', result.error);
        return {
          status: 'disconnected',
          slowQueries: this.slowQueries
        };
      }
      
      return result.data as DiagnosticResult['databaseHealth'];
    } catch (error) {
      console.error('Erro no diagn├│stico do banco', (error as Error).message);
      
      // Registrar no audit_log
      try {
        const tenantId = getDiagnosticTenantId();
        if (!tenantId) {
          return {
            status: 'disconnected',
            slowQueries: this.slowQueries
          };
        }
        await registerDiagnosticAudit(tenantId, {
          timestamp: new Date(),
          systemHealth: await this.checkSystemHealth(),
          databaseHealth: { status: 'disconnected', slowQueries: this.slowQueries },
          routeHealth: await this.checkRouteHealth(),
          queueHealth: await this.checkQueueHealth(),
          serviceHealth: await this.checkServiceHealth(),
        });
      } catch (auditError) {
        console.error(`Erro ao registrar diagn├│stico no audit_log: ${(auditError as Error).message}`);
      }

      return {
        status: 'disconnected',
        slowQueries: this.slowQueries
      };
    }
  }

  /**
   * Verifica sa├║de das rotas
   */
  private async checkRouteHealth(): Promise<DiagnosticResult['routeHealth']> {
    const recentErrors = this.routeErrors.filter(
      e => Date.now() - e.timestamp.getTime() < 300000 // ├║ltimos 5 minutos
    );

    const totalRequests = 100; // Simulado - deveria vir de metrics
    const errorRate = totalRequests > 0 ? (recentErrors.length / totalRequests) * 100 : 0;

    let avgResponseTime = 0; // Simulado - deveria vir de metrics

    return {
      totalRoutes: totalRequests,
      errorRate,
      avgResponseTime,
      errors: recentErrors
    };
  }

  /**
   * Verifica sa├║de das filas
   */
  private async checkQueueHealth(): Promise<DiagnosticResult['queueHealth']> {
    try {
      // Simula├º├úo - deveria verificar filas reais
      const pendingJobs = 0;
      const processingJobs = 0;
      const failedJobs = this.serviceErrors.get('queue') || 0;

      let status: 'active' | 'stalled' | 'empty' = 'active';
      
      if (pendingJobs === 0 && processingJobs === 0) {
        status = 'empty';
      } else if (failedJobs > 10) {
        status = 'stalled';
      }

      return {
        status,
        pendingJobs,
        processingJobs,
        failedJobs
      };

    } catch (error) {
      console.error('Erro ao verificar sa├║de das filas', (error as Error).message);
      return {
        status: 'stalled',
        pendingJobs: 0,
        processingJobs: 0,
        failedJobs: 999
      };
    }
  }

  /**
   * Verifica sa├║de dos servi├ºos
   */
  private async checkServiceHealth(): Promise<DiagnosticResult['serviceHealth']> {
    const services = ['auth-service', 'payment-service', 'stock-service', 'notification-service'];
    const serviceHealth: DiagnosticResult['serviceHealth'] = {};

    for (const service of services) {
      const errorCount = this.serviceErrors.get(service) || 0;
      serviceHealth[service] = {
        status: errorCount > 5 ? 'error' : 'healthy',
        errorCount
      };
    }

    return serviceHealth;
  }

  /**
   * Avalia sa├║de geral baseado em todos os fatores
   */
  private evaluateOverallHealth(result: DiagnosticResult): void {
    const criticalIssues: string[] = [];

    if (result.databaseHealth.status === 'disconnected') {
      criticalIssues.push('Database disconnected');
    }

    if (result.systemHealth.status === 'critical') {
      criticalIssues.push('Critical memory usage');
    }

    if (result.queueHealth.status === 'stalled') {
      criticalIssues.push('Queue stalled');
    }

    if (criticalIssues.length > 0) {
      console.error('SISTEMA EM ESTADO CR├ìTICO', { criticalIssues });
    }
  }

  /**
   * Registra resultado do diagn├│stico no audit_log
   */
  private async registerDiagnosticResult(result: DiagnosticResult): Promise<void> {
    try {
      const tenantId = getDiagnosticTenantId();
      if (!tenantId) {
        return;
      }
      await registerDiagnosticAudit(tenantId, result);
    } catch (error) {
      console.error(`Erro ao registrar diagn├│stico no audit_log: ${(error as Error).message}`);
    }
  }

  /**
   * Registra query lenta para monitoramento
   */
  public registerSlowQuery(query: string, duration: number): void {
    this.slowQueries.push({
      query,
      duration,
      timestamp: new Date()
    });

    // Manter apenas ├║ltimas 100 queries lentas
    if (this.slowQueries.length > 100) {
      this.slowQueries = this.slowQueries.slice(-50);
    }

    // Alertar se muitas queries lentas
    if (this.slowQueries.length > 10) {
      console.warn('M├║ltiplas queries lentas detectadas', {
        count: this.slowQueries.length,
        recentQuery: query,
        duration
      });
    }
  }

  /**
   * Registra erro de rota para monitoramento
   */
  public registerRouteError(route: string, error: string): void {
    this.routeErrors.push({
      route,
      error,
      timestamp: new Date()
    });

    // Manter apenas ├║ltimos 100 erros
    if (this.routeErrors.length > 100) {
      this.routeErrors = this.routeErrors.slice(-50);
    }
  }

  /**
   * Registra erro de servi├ºo para monitoramento
   */
  public registerServiceError(serviceName: string): void {
    const currentCount = this.serviceErrors.get(serviceName) || 0;
    this.serviceErrors.set(serviceName, currentCount + 1);

    console.warn(`Erro registrado no servi├ºo ${serviceName}`, {
      errorCount: currentCount + 1
    });
  }

  /**
   * Obt├®m relat├│rio simplificado do diagn├│stico
   */
  public getDiagnosticSummary(): string {
    if (this.diagnosticHistory.length === 0) {
      return 'Nenhum diagn├│stico dispon├¡vel';
    }

    const latest = this.diagnosticHistory[this.diagnosticHistory.length - 1];
    
    return `
=== DIAGN├ôSTICO ERP ===
Timestamp: ${latest.timestamp.toISOString()}
Sistema: ${latest.systemHealth.status} (Uptime: ${Math.floor(latest.systemHealth.uptime / 60)}min)
Banco: ${latest.databaseHealth.status} (${latest.databaseHealth.slowQueries.length} queries lentas)
Filas: ${latest.queueHealth.status} (${latest.queueHealth.failedJobs} falhas)
Servi├ºos: ${Object.values(latest.serviceHealth).filter(s => s.status === 'healthy').length}/${Object.keys(latest.serviceHealth).length} saud├íveis
    `.trim();
  }
}

// Exportar singleton
export const systemDiagnostic = SystemDiagnostic.getInstance();

