  console.log(`ÔØî Requests falhadas: ${report.summary.failedRequests}/${report.summary.totalRequests}`);
  console.log(`­ƒôè Taxa de sucesso: ${report.summary.successRate.toFixed(2)}%`);

  console.log('\nÔÅ▒´©Å TEMPOS DE RESPOSTA (ms):');
  console.log(`­ƒôÅ M├®dia: ${report.summary.averageResponseTime.toFixed(2)}`);
  console.log(`ÔÜí M├¡nimo: ${report.summary.minResponseTime.toFixed(2)}`);
  console.log(`­ƒÉî M├íximo: ${report.summary.maxResponseTime.toFixed(2)}`);

  console.log('\n­ƒöì VALIDA├ç├âO DE INTEGRIDADE:');
  console.log(`­ƒöä Pedidos duplicados: ${report.summary.duplicatePedidos}`);
  console.log(`­ƒåö Trace IDs ├║nicos: ${report.summary.uniqueTraceIds}`);
  console.log(`­ƒÆÑ Colis├Áes de traceId: ${report.traceIdCollisions.length}`);

  if (report.duplicates.length > 0) {
    console.log('\nÔØî DUPLICA├ç├òES ENCONTRADAS:');
    report.duplicates.forEach(dup => {
      console.log(`   Pedido ID ${dup.pedidoId}: ${dup.count} ocorr├¬ncias`);
      console.log(`   Trace IDs: ${dup.traceIds.join(', ')}`);
    });
  }

  if (report.traceIdCollisions.length > 0) {
    console.log('\nÔÜá´©Å COLIS├òES DE TRACE ID:');
    report.traceIdCollisions.forEach(collision => {
      console.log(`   TraceId ${collision.traceId}: ${collision.count} ocorr├¬ncias`);
    });
  }

  if (report.summary.errors.length > 0) {
    console.log('\n­ƒÜ¿ ERROS ENCONTRADOS:');
    report.summary.errors.forEach(({ error, count }) => {
      console.log(`   ${error}: ${count} ocorr├¬ncias`);
    });
  }

  // Verifica├º├úo cr├¡tica
  console.log('\n­ƒöÑ VERIFICA├ç├âO CR├ìTICA:');
  if (report.summary.duplicatePedidos > 0) {
    console.log('ÔØî FALHA CR├ìTICA: Pedidos duplicados detectados!');
    process.exit(1);
  }

  if (report.traceIdCollisions.length > 0) {
    console.log('ÔØî FALHA CR├ìTICA: Colis├Áes de traceId detectadas!');
    process.exit(1);
  }

  if (report.summary.successRate < 95) {
    console.log('ÔØî FALHA: Taxa de sucesso abaixo de 95%!');
    process.exit(1);
  }

  console.log('Ô£à TESTE PASSOU: Sistema resistiu ├á concorr├¬ncia!');
}

async function main(): Promise<void> {
  try {
    const report = await runConcurrencyTest();
