export { runResilienceTest, ResilienceTestReport };

import { performance } from 'perf_hooks';
import axios, { AxiosError } from 'axios';
import { randomUUID } from 'crypto';
import { Worker, isMainThread, parentPort, workerData } from 'worker_threads';

interface TracingWorkerData {
  baseUrl: string;
  requestsPerWorker: number;
  workerId: number;
  timeout: number;
}

interface TracingTestMetric {
  timestamp: number;
  workerId: number;
  requestId: string;
  success: boolean;
  responseTime: number;
  status?: number;
  error?: string;
  traceId?: string;
  spanId?: string;
  parentTraceId?: string;
  hasTraceHeader: boolean;
  traceHeaderValid: boolean;
  spansCompleted: number;
  spansLeaked: number;
  memoryUsage: NodeJS.MemoryUsage;
}

interface TracingTestReport {
  timestamp: string;
  config: {
    baseUrl: string;
    totalRequests: number;
    workers: number;
    timeout: number;
  };
  metrics: TracingTestMetric[];
  summary: {
    totalRequests: number;
    successfulRequests: number;
    failedRequests: number;
    averageResponseTime: number;
    traceIdUniqueness: number;
    traceHeaderRate: number;
    spansCompletionRate: number;
