  };
  issues: {
    duplicateTraceIds: Array<{ traceId: string; count: number; requestIds: string[] }>;
    missingTraceHeaders: number;
    invalidTraceHeaders: number;
    leakedSpans: number;
    memoryLeaks: boolean;
  };
}

