    report.issues.leakedSpans > report.summary.totalRequests * 0.05
  ].filter(Boolean).length;

  if (criticalIssues === 0) {
    console.log('Ô£à TESTE PASSOU: Sistema de tracing est├í funcionando corretamente!');
  } else {
    console.log(`ÔØî TESTE FALHOU: ${criticalIssues} problemas cr├¡ticos encontrados!`);
  }
}

async function main(): Promise<void> {
  const baseUrl = process.env.BASE_URL || 'http://localhost:3001';
  const totalRequests = parseInt(process.env.TRACING_REQUESTS || '100');

  try {
    const report = await runTracingTest(baseUrl, totalRequests);
    printReport(report);

    // Salva relat├│rio
    const fs = await import('fs/promises');
    await fs.writeFile(
      `./tracing-test-report-${Date.now()}.json`,
      JSON.stringify(report, null, 2)
    );

    console.log(`\n­ƒÆ¥ Relat├│rio salvo em: tracing-test-report-${Date.now()}.json`);

  } catch (error) {
    console.error('ÔØî Erro ao executar teste:', error);
    process.exit(1);
  }
}

// Executa como worker se receber dados
if (!isMainThread && workerData) {
  workerFunction(workerData as TracingWorkerData)
    .then(metrics => {
      if (parentPort) {
        parentPort.postMessage(metrics);
      }
    })
    .catch(error => {
      console.error('Worker error:', error);
      process.exit(1);
    });
}

// Executa como main se chamado diretamente
if (isMainThread && require.main === module) {
  main().catch(console.error);
}

