async function testTransactionRollback(): Promise<TestResult> {
  const start = Date.now();
  try {
    console.log("3´©ÅÔâú TESTE: Rollback de Transa├º├úo");
    console.log("ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ");

    const db = await getDb();

    // Get initial count
    const countBefore = (await db.select({ count: count() }).from(pedidos).where(eq(pedidos.tenantId, TEST_TENANT_ID)))[0]
      ?.count || 0;

    // Tentar criar e depois fallhar
    try {
      await db.transaction(async tx => {
        // Step 1: Insert
        await tx.insert(pedidos).values({
          tenantId: TEST_TENANT_ID,
          numero: Math.floor(Math.random() * 1000000),
          vendedorId: 1,
          clienteId: 1,
          clienteNome: "Teste Rollback",
          status: "GERADO",
          subtotal: 100,
          desconto: 0,
          frete: 0,
          total: 100,
        });

        // Step 2: Force error
        throw new Error("Teste erro intencional");
      });
    } catch (e) {
      // Expected
    }

    // Get count after
    const countAfter = (await db.select({ count: count() }).from(pedidos).where(eq(pedidos.tenantId, TEST_TENANT_ID)))[0]
      ?.count || 0;

    const rollbackWorked = countBefore === countAfter;

    if (rollbackWorked) {
      console.log("Ô£à Rollback funcionou (dados revertidos)");
    } else {
      console.log(`ÔØî Rollback FALHOU (dados n├úo foram revertidos)`);
      console.log(`   Antes: ${countBefore}, Depois: ${countAfter}`);
    }
    console.log("");

    return {
      name: "Transaction Rollback",
      passed: rollbackWorked,
      duration: Date.now() - start,
      message: rollbackWorked ? "Transa├º├úo OK" : "FALHOU",
    };
  } catch (error: any) {
    console.log(`ÔØî Erro: ${error.message}`);
    console.log("");

    return {
      name: "Transaction Rollback",
      passed: false,
      duration: Date.now() - start,
      message: error.message,
      error: error.stack,
    };
  }
}

